// Wraps src/glossary.json as a script the content script can load without fetching.
const fs = require("fs"), path = require("path");
const src = path.join(__dirname, "..", "src");
const data = JSON.parse(fs.readFileSync(path.join(src, "glossary.json"), "utf8"));
fs.writeFileSync(path.join(src, "glossary.js"),
  "/* generated by scripts/build-glossary.js from glossary.json: do not edit */\n" +
  "globalThis.JargonLens = Object.assign(globalThis.JargonLens || {}, { BUILTIN: " + JSON.stringify(data) + " });\n");
console.log("glossary.js written:", data.length, "terms");
